CREATE TABLE IF NOT EXISTS variants (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, kind VARCHAR(16) NOT NULL, target VARCHAR(128) NOT NULL, `name` VARCHAR(120) NOT NULL, binding VARCHAR(16) NOT NULL, version INT NOT NULL, endpoint VARCHAR(2048) NULL, config text NOT NULL, shared_secret text NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, CONSTRAINT fk_variants_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE variants ADD CONSTRAINT variant_team_slot_name UNIQUE (team_id, kind, target, `name`);
CREATE TABLE IF NOT EXISTS variant_assignments (member_id VARCHAR(36), kind VARCHAR(16), target VARCHAR(128), team_id VARCHAR(36) NOT NULL, variant_id VARCHAR(36) NOT NULL, `source` VARCHAR(16) NOT NULL, member_secret text NULL, assigned_at BIGINT NOT NULL, CONSTRAINT pk_variant_assignments PRIMARY KEY (member_id, kind, target), CONSTRAINT fk_variant_assignments_member_id__id FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_variant_assignments_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_variant_assignments_variant_id__id FOREIGN KEY (variant_id) REFERENCES variants(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX variant_assignment_variant ON variant_assignments (variant_id);
CREATE INDEX variant_assignment_team ON variant_assignments (team_id, member_id);
CREATE TABLE IF NOT EXISTS variant_exclusions (member_id VARCHAR(36), kind VARCHAR(16), target VARCHAR(128), team_id VARCHAR(36) NOT NULL, created_at BIGINT NOT NULL, CONSTRAINT pk_variant_exclusions PRIMARY KEY (member_id, kind, target), CONSTRAINT fk_variant_exclusions_member_id__id FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_variant_exclusions_team_id__id FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX variant_exclusion_team ON variant_exclusions (team_id, member_id);
